"""Test claims generated by code (not by a model) to probe a drafted rule.

Starting from a few varied synthetic base claims, the generator changes the
fields the drafted spec reads, towards the edges where rules usually go
wrong: missing or blank values, values just below / at / just above every
number the rule compares against, boundary dates, other known and unknown
codes, duplicated or removed list entries. Every case must still pass the claim
schema and transport checks, because the rule engine never sees anything else.

Fields the rule's English text names but the spec never reads are probed too
(missing, then one other value). A draft that silently drops part of the rule
then shows an outcome the author can see is wrong in the case table. A few
claims combine a missing value with a violation, to show which of the two wins.
"""

from __future__ import annotations

import copy
import json
import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date, timedelta
from decimal import Decimal
from typing import Any, Callable

from normalisation.schema_subset import validate as validate_claim_schema
from rule_engine.catalogue import DATE, LIST, NUMBER, OBJECT, TEXT, FieldCatalogue, ReferenceData
from rule_engine.engine_core import validate_transport
from rule_engine.interpreter import EvaluationLimitExceeded, evaluate_rule
from rule_engine.language import ConfigValue, DaysBetweenValue, LiteralValue, Node, RuleSpec
from rule_engine.validation import analyse_spec

DEFAULT_LIMIT = 40
LIST_FIELDS = ("/lines", "/authorizations", "/attachments")
UNREAD_PROBES = 2  # cases per base claim for a field the text names but the spec never reads
MAX_COMBINED = 6  # claims with a missing value and a violation together, beyond the limit
MAX_LIST_SIZE = 30  # the largest list built to test a count named in the rule
MAX_CANDIDATES = 18  # values tried per field and base claim
FREE_TEXT = ("notes", "text")  # untrusted free text: never varied
LIST_IDS = {"lines": "line_id", "attachments": "attachment_id", "authorizations": "authorization_id"}


@dataclass
class EdgeCase:
    case_id: str
    description: str
    claim: dict[str, Any]
    # The claim field this case changes ("" for an unchanged claim, "a + b" for two changes),
    # so outcomes can be reviewed and corrected one field at a time.
    field: str = ""


@dataclass
class LabelledCase:
    """A test claim whose correct outcome the rule's author has confirmed."""

    description: str
    claim: dict[str, Any]
    expected_status: str
    # A claim the author gave (not a generated test claim): the drafter is shown its content.
    shown: bool = False
    # An outcome a draft already gave and the author confirmed while reviewing it: nothing to
    # change, but every later draft must keep it.
    confirmed: bool = False

    def to_json(self) -> dict[str, Any]:
        return {"description": self.description, "claim": self.claim, "expected_status": self.expected_status,
                "shown": self.shown, "confirmed": self.confirmed}

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> "LabelledCase":
        return cls(description=data["description"], claim=data["claim"], expected_status=data["expected_status"],
                   shown=data.get("shown", False), confirmed=data.get("confirmed", False))


@dataclass
class _Hints:
    """What the spec itself says about interesting values."""

    numbers: set = field(default_factory=set)
    texts: set = field(default_factory=set)
    dates: set = field(default_factory=set)
    policy_fields: set = field(default_factory=set)
    uses_day_counts: bool = False

    @classmethod
    def from_spec(cls, spec: RuleSpec) -> "_Hints":
        hints = cls()
        for node in _walk(spec):
            if isinstance(node, LiteralValue):
                literal = node.value
                if isinstance(literal, bool):
                    continue
                if isinstance(literal, (int, float)):
                    hints.numbers.add(literal)
                elif _parse_date(literal):
                    hints.dates.add(literal)
                elif literal:
                    hints.texts.add(literal)
            elif isinstance(node, ConfigValue) and node.config == "policy" and node.get:
                if isinstance(node.get[0], str):
                    hints.policy_fields.add(node.get[0])
            elif isinstance(node, DaysBetweenValue):
                hints.uses_day_counts = True
        return hints


Mutation = tuple[str, Callable[[dict[str, Any]], None]]


class EdgeCaseGenerator:
    def __init__(
        self,
        base_claims: list[dict[str, Any]],
        fields: FieldCatalogue,
        reference: ReferenceData,
        claim_schema: dict[str, Any],
        limit: int = DEFAULT_LIMIT,
    ):
        self.base_claims = base_claims
        self.fields = fields
        self.reference = reference
        self.claim_schema = claim_schema
        self.limit = limit

    def generate(self, spec: RuleSpec, rule: dict[str, Any] | None = None) -> list[EdgeCase]:
        """The test claims for a spec. Pass the rule to also probe the fields its text
        names; the same spec and rule always give the same cases and case ids."""
        read = analyse_spec(spec, self.fields).fields_read
        fields_read = sorted(read)
        unread = sorted({
            path for group in fields_mentioned(rule_text(rule), self.fields) if not group & read for path in group
        }) if rule else []
        hints = _Hints.from_spec(spec)
        # Codes the text names are tried too, even when the spec dropped them ("MEM-").
        hints.texts |= {value for value in values_mentioned(rule_text(rule)) if _CODE.fullmatch(value)}

        by_base: dict[str, list[list[tuple[dict, Mutation]]]] = {}
        for label, base in zip("ABCDEF", self.base_claims):
            for path in fields_read:
                by_base.setdefault(path, []).append(
                    [(base, mutation) for mutation in self._mutations(path, base, label, fields_read, hints)])
            for path in unread:
                by_base.setdefault(path, []).append(
                    [(base, mutation) for mutation in self._mutations(path, base, label, fields_read, hints)[:UNREAD_PROBES]])
        groups: dict[str, list[tuple[dict, Mutation]]] = {path: self._order(lists) for path, lists in by_base.items()}

        cases: list[EdgeCase] = []
        seen: set[str] = set()

        def add(description: str, claim: dict[str, Any], field: str) -> bool:
            key = json.dumps(claim, sort_keys=True)
            if key in seen or not self._is_valid(claim):
                return False
            seen.add(key)
            cases.append(EdgeCase(case_id=f"c{len(cases) + 1}", description=description, claim=claim, field=field))
            return True

        for label, base in zip("ABCDEF", self.base_claims):
            add(f"claim {label} unchanged", copy.deepcopy(base), "")

        # Round-robin over the fields so every field the rule reads gets probed.
        singles: list[tuple[dict, str, Mutation, str]] = []  # base, field, mutation, the spec's outcome
        while groups and len(cases) < self.limit:
            for path in list(groups):
                if not groups[path]:
                    del groups[path]
                    continue
                base, (description, mutate) = groups[path].pop(0)
                claim = copy.deepcopy(base)
                mutate(claim)
                if add(description, claim, path):
                    singles.append((base, path, (description, mutate), self._status(spec, claim)))
                if len(cases) >= self.limit:
                    break

        self._add_combined(singles, add)
        return cases

    def _order(self, lists: list[list[tuple[dict, Mutation]]]) -> list[tuple[dict, Mutation]]:
        """The order one field's changes are tried in, from each base claim's list of changes:
        diverse rather than numerous, since a rule reading 20 fields gets about 2 per field.

        - A blank text is left out where "missing" is tried: the engine reads them alike.
        - The first kind (usually "missing") goes on two claims first: the same change means
          different things in different places (a missing date on an imaging line or on a lab
          line; R010 was wrong only on the lab line).
        - Then each change is a kind not yet tried for this field, on the claim used least
          (an unknown code exposed R009, a negative quantity R013).

        On the 29 wrong proposals of past benchmark runs, at the same 40-claim budget, this
        exposes all 29; trying each kind on every claim in turn exposed 25, and 60 claims in
        that order still 25.
        """
        lists = [[entry for entry in rows
                  if not (_kind(entry) == "blank" and any(_kind(other) == "missing" for other in rows))]
                 for rows in lists]
        lists = [rows for rows in lists if rows]
        if not lists:
            return []
        ordered = [rows[0] for rows in lists[:2]]
        kinds_tried = {_kind(entry) for entry in ordered}
        claims_used = Counter(range(len(ordered)))
        pool = [(position, index, entry) for index, rows in enumerate(lists) for position, entry in enumerate(rows)
                if not (position == 0 and index < 2)]
        while pool:
            best = min(pool, key=lambda item: (_kind(item[2]) in kinds_tried, claims_used[item[1]], item[0], item[1]))
            pool.remove(best)
            kinds_tried.add(_kind(best[2]))
            claims_used[best[1]] += 1
            ordered.append(best[2])
        return ordered

    def _add_combined(self, singles, add) -> None:
        """A missing value and a violation in the same claim.

        One change at a time never shows which of the two wins, and rules differ
        exactly there ("missing data leaves UNABLE_TO_ASSESS unless a known
        violation exists"). Each change that left the spec unable to assess is
        paired with a change, to another field of the same claim, that failed it.
        """
        unknown = [single for single in singles if single[3] == "UNABLE_TO_ASSESS"]
        failing = [single for single in singles if single[3] == "FAIL"]
        added = 0
        for base, path, (description, mutate), _ in unknown:
            partners = [single for single in failing if single[0] is base and single[1] != path]
            turn = added % len(partners) if partners else 0  # rotate, so different violations get paired
            for _, other_path, (other_description, other_mutate), _ in partners[turn:] + partners[:turn]:
                claim = copy.deepcopy(base)
                mutate(claim)
                other_mutate(claim)
                if add(f"{description}, and {other_description.split(': ', 1)[-1]}", claim, f"{path} + {other_path}"):
                    added += 1
                    break
            if added >= MAX_COMBINED:
                return

    def _status(self, spec: RuleSpec, claim: dict[str, Any]) -> str:
        try:
            return evaluate_rule(spec, claim, self.reference).status
        except EvaluationLimitExceeded:
            return "ERROR"

    # --------------------------------------------------------------- mutations

    def _mutations(self, path, base, label, fields_read, hints) -> list[Mutation]:
        if path in LIST_FIELDS:
            return self._list_mutations(path, base, label, hints)
        info = self.fields.get(path)
        located = _locate(base, path)
        if info is None or located is None:
            return []
        container, key, shown = located
        current = container[key]
        mutations = []
        for value, why in self._candidates(path, info, current, base, fields_read, hints):
            if value == current and why != "unchanged":
                continue
            description = f"claim {label}: {shown} = {json.dumps(value)} ({why}; was {json.dumps(current)})"
            mutations.append((description, _setter(path, value)))
        return mutations

    def _candidates(self, path, info, current, base, fields_read, hints):
        candidates: list[tuple[Any, str]] = []
        if info.nullable:
            candidates.append((None, "missing"))
        if TEXT in info.types:
            candidates.append(("", "blank"))
            # Another non-empty value: without it, a rule that two fields must be equal
            # ("member id equals the coverage's member id") is never broken by any test claim.
            if isinstance(current, str) and current and path.rsplit("/", 1)[-1] not in FREE_TEXT:
                candidates.append((f"{current}-OTHER", "a different value"))
            candidates.extend((text, "value named in the rule") for text in sorted(hints.texts))
            candidates.extend((text.lower(), "different letter case") for text in sorted(hints.texts) if text.lower() != text)
            candidates.extend(self._domain_values(path, base))
        if NUMBER in info.types:
            for number in sorted(hints.numbers | self._policy_numbers(base, hints)):
                candidates.extend(_around(number))
            candidates.append((0, "zero"))
            candidates.append((-1, "negative"))
            if isinstance(current, (int, float)) and not isinstance(current, bool):
                candidates.append((round(current + 0.01, 2), "one cent more"))
                candidates.append((current * 2, "doubled"))
        if DATE in info.types:
            for literal in sorted(hints.dates):
                candidates.extend(_shift_all(literal, "date named in the rule"))
            for other in fields_read:
                if other != path and DATE in getattr(self.fields.get(other), "types", ()):
                    located = _locate(base, other)
                    other_value = located[0][located[1]] if located else None
                    if _parse_date(other_value):
                        candidates.extend(_shift_all(other_value, f"relative to {other}"))
                        if hints.uses_day_counts:
                            # Every day count the rule uses (from the policy or written in the
                            # rule), on both sides of the other date: a rule that counts the
                            # days the wrong way round only shows on the side it ignores.
                            literals = {number for number in hints.numbers if isinstance(number, int) and not isinstance(number, bool)}
                            for days in sorted(self._policy_numbers(base, hints) | literals):
                                if isinstance(days, int) and 0 < days < 3650:
                                    candidates.extend(_shift_all(_add_days(other_value, -days), f"{days} days before {other}"))
                                    candidates.extend(_shift_all(_add_days(other_value, days), f"{days} days after {other}"))
            if _parse_date(current):
                candidates.extend(_shift_all(current, "current date"))
        return candidates[:MAX_CANDIDATES]

    def _domain_values(self, path: str, base: dict[str, Any]) -> list[tuple[Any, str]]:
        name = path.rsplit("/", 1)[-1]
        policy = self.reference.policies.get(base.get("policy_id"), {})
        if name == "service_code":
            special = sorted(set(policy.get("auth_required_services", [])) | set(policy.get("required_documents", {})))
            ordinary = [code for code in sorted(self.reference.services) if code not in special]
            return [(code, "known service code") for code in (special[:2] + ordinary[:1])] + [("SVC-UNKNOWN", "unknown service code")]
        if name == "provider_id":
            allowed = policy.get("allowed_providers", [])
            others = [pid for pid in self.reference.provider_ids if pid not in allowed]
            return [(pid, "allowed provider") for pid in allowed[:1]] + [(pid, "known provider not allowed by the policy") for pid in others[:1]] + [("EDU-PROV-UNKNOWN", "unknown provider")]
        if name == "policy_id":
            return [(pid, "other policy") for pid in sorted(self.reference.policies) if pid != base.get("policy_id")] + [("EDU-UNKNOWN-POLICY", "unknown policy")]
        if name == "diagnosis_code":
            return [(code, "known diagnosis") for code in self.reference.diagnosis_codes[:2]] + [("DX-UNKNOWN", "unknown diagnosis")]
        if name == "currency":
            return [("USD", "other currency")]
        return []

    def _policy_numbers(self, base: dict[str, Any], hints: _Hints) -> set:
        """Numbers from the claim's policy fields that the rule reads (e.g. price limits)."""
        policy = self.reference.policies.get(base.get("policy_id"), {})
        codes = {line.get("service_code") for line in base.get("lines", [])}
        numbers = set()
        for name in hints.policy_fields:
            value = policy.get(name)
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                numbers.add(value)
            elif isinstance(value, dict):
                numbers.update(v for code, v in value.items() if code in codes and isinstance(v, (int, float)))
        return numbers

    def _list_mutations(self, path: str, base: dict[str, Any], label: str, hints: _Hints) -> list[Mutation]:
        name = path.strip("/")
        items = base.get(name) or []
        mutations: list[Mutation] = []
        if items:
            def duplicate(claim, name=name):
                twin = copy.deepcopy(claim[name][0])
                if name == "lines":
                    twin["line_id"] = f"{twin['line_id']}-DUP"
                claim[name].append(twin)
            mutations.append((f"claim {label}: first entry of {name} duplicated", duplicate))
            # A rule counting entries ("at most 5 lines") needs lists around that count.
            counts = sorted({size for number in hints.numbers if isinstance(number, int) and 0 < number <= MAX_LIST_SIZE
                             for size in (number - 1, number, number + 1)} - {len(items), 0})
            for size in counts:
                if size <= MAX_LIST_SIZE:
                    mutations.append((f"claim {label}: {name} with {size} entries (was {len(items)})",
                                      lambda claim, name=name, size=size: _resize(claim, name, size)))
        if name != "lines" and items:
            mutations.append((f"claim {label}: {name} emptied", lambda claim, name=name: claim.__setitem__(name, [])))
        return mutations

    def _is_valid(self, claim: dict[str, Any]) -> bool:
        try:
            validate_claim_schema(claim, self.claim_schema)
            validate_transport(claim)
        except (ValueError, KeyError, TypeError):
            return False
        return True


def choose_base_claims(claims: list[dict[str, Any]], count: int = 3) -> list[dict[str, Any]]:
    """Pick varied base claims deterministically, so edge cases have context to work with."""
    criteria = [
        # authorizations and documents, for rules about them
        lambda claim, chosen: bool(claim["authorizations"]) and bool(claim["attachments"]),
        # several lines and no authorizations, for line-level and duplicate rules
        lambda claim, chosen: len(claim["lines"]) > 1 and not claim["authorizations"],
        # a policy not used yet, for policy-dependent rules
        lambda claim, chosen: all(claim["policy_id"] != other["policy_id"] for other in chosen),
    ]
    chosen: list[dict[str, Any]] = []
    for matches in criteria:
        match = next((claim for claim in claims if claim not in chosen and matches(claim, chosen)), None)
        if match is not None:
            chosen.append(match)
    for claim in claims:
        if len(chosen) >= count:
            break
        if claim not in chosen:
            chosen.append(claim)
    return chosen[:count]


def rule_text(rule: dict[str, Any] | None) -> str:
    """The parts of a rule that describe what it checks (not the corrective action)."""
    if not rule:
        return ""
    return f"{rule.get('title', '')}. {rule.get('logic', '')}"


def fields_mentioned(text: str, fields: FieldCatalogue) -> list[frozenset[str]]:
    """The claim fields a rule's text names, one group of candidate paths per name.

    A name counts as an identifier (service_date, coverage.end_date) or as words
    (service date, invoice number). An identifier that continues does not count
    (max_quantity_per_line is not max_quantity), and the longest name wins
    (document status is document_status, not status). A name several fields share
    narrows to the one whose parent is named just before it ("coverage status",
    "line service_date"); otherwise every field with that name is a candidate.
    """
    by_name: dict[str, list[tuple[str, str]]] = {}
    for path in fields.fields:
        parts = [part for part in path.strip("/").split("/") if part != "*"]
        info = fields.get(path)
        if info is None or path.endswith("*") or info.types & {OBJECT, LIST}:
            continue  # containers: a rule about lines is probed through what it reads in them
        by_name.setdefault(parts[-1], []).append((path, parts[-2] if len(parts) > 1 else ""))

    text = text.lower()
    groups: list[frozenset[str]] = []
    for name in sorted(by_name, key=len, reverse=True):
        words = r"\s+".join(map(re.escape, name.split("_")))
        pattern = re.compile(rf"(?<![a-z0-9_])(?:{re.escape(name)}|{words})(?![a-z0-9_])")
        for match in pattern.finditer(text):
            before = re.search(r"([a-z0-9_]+)[\s.]*$", text[:match.start()])
            parent = before.group(1).rstrip("s") if before else ""
            named = [path for path, owner in by_name[name] if owner and owner.rstrip("s") == parent]
            groups.append(frozenset(named or [path for path, _ in by_name[name]]))
        text = pattern.sub(lambda found: " " * len(found.group(0)), text)  # a longer name took these words
    return groups


_CODE = re.compile(r"\b[A-Z][A-Z0-9]*(?:-[A-Z0-9]*)+")  # SVC-CONSULT, EDU-PROV-01, MEM-
_DATE_TEXT = re.compile(r"\b\d{4}-\d{2}-\d{2}\b")
# A number on its own; "2 decimal places" is money precision, which the language fixes.
_NUMBER_TEXT = re.compile(r"(?<![\w.-])\d+(?:\.\d+)?(?![\w-]|\.\d)(?!\s*decimal)")


def values_mentioned(text: str) -> list[str]:
    """Codes, dates and numbers a rule's text names, in order, without repeats."""
    found: list[str] = []
    for pattern in (_CODE, _DATE_TEXT):
        found += pattern.findall(text)
        text = pattern.sub(" ", text)
    found += _NUMBER_TEXT.findall(text)
    return list(dict.fromkeys(found))


def unused_values(rule: dict[str, Any], spec: RuleSpec) -> list[str]:
    """Values the rule's text names that the spec never uses.

    Often a sign the draft left part of the rule out, for instance because the
    language cannot express it ("must start with MEM-"). A value counts as used
    when the spec holds it exactly, as a prefix of one of its texts ("MEM-" in
    "MEM-0001"), or as one part of a date ("2026" in "2026-01-01").
    """
    texts: set[str] = set()
    numbers: set[Decimal] = set()
    for node in _walk(spec):
        for name in type(node).model_fields:
            if name in ("note", "path", "op"):
                continue
            values = getattr(node, name)
            for value in values if isinstance(values, list) else [values]:
                if isinstance(value, bool):
                    continue
                if isinstance(value, (int, float)):
                    numbers.add(Decimal(str(value)).normalize())
                elif isinstance(value, str):
                    texts.add(value)

    def used(mention: str) -> bool:
        if _NUMBER_TEXT.fullmatch(mention) and Decimal(mention).normalize() in numbers:
            return True
        return any(text.startswith(mention) or mention in re.split(r"[^A-Za-z0-9.]+", text) for text in texts)

    return [mention for mention in values_mentioned(rule_text(rule)) if not used(mention)]


# ------------------------------------------------------------------ helpers


def _walk(node: Node):
    pending = [node]
    while pending:
        current = pending.pop()
        yield current
        for name in type(current).model_fields:
            child = getattr(current, name)
            children = child if isinstance(child, list) else [child]
            pending.extend(item for item in children if isinstance(item, Node))


def _locate(claim: dict[str, Any], path: str):
    """Container, key and a readable label for a catalogue path (first list element)."""
    container: Any = claim
    parts = path.strip("/").split("/")
    shown: list[str] = []
    for index, part in enumerate(parts):
        last = index == len(parts) - 1
        if part == "*":
            if not isinstance(container, list) or not container:
                return None
            container = container[0]
            shown[-1] += "[0]"
            continue
        if not isinstance(container, dict) or part not in container:
            return None
        shown.append(part)
        if last:
            return container, part, ".".join(shown)
        container = container[part]
    return None


def _resize(claim: dict[str, Any], name: str, size: int) -> None:
    """Cut a list to `size` entries, or grow it with copies (each with its own id)."""
    items = claim[name]
    originals = list(items)
    del items[size:]
    key = LIST_IDS.get(name)
    while len(items) < size:
        twin = copy.deepcopy(originals[len(items) % len(originals)])
        if key and key in twin:
            twin[key] = f"{twin[key]}-COPY{len(items) + 1}"
        items.append(twin)


_WHY = re.compile(r"\(([^;()]+); was ")


def _kind(entry: tuple[dict, Mutation]) -> str:
    return change_kind(entry[1][0])


def change_kind(description: str) -> str:
    """The kind of change a test claim makes ("missing", "blank", "a different value", ...), read
    from the description _mutations writes; a list change is its own kind ("authorizations emptied")."""
    match = _WHY.search(description)
    return match.group(1) if match else description.split(": ", 1)[-1]


def _setter(path: str, value: Any) -> Callable[[dict[str, Any]], None]:
    def mutate(claim: dict[str, Any]) -> None:
        located = _locate(claim, path)
        if located is not None:
            container, key, _ = located
            container[key] = value
    return mutate


def _around(number) -> list[tuple[Any, str]]:
    step = 1 if isinstance(number, int) else 0.01
    return [
        (round(number - step, 2), f"just below {number}"),
        (number, f"exactly {number}"),
        (round(number + step, 2), f"just above {number}"),
    ]


def _parse_date(value: Any) -> date | None:
    if not isinstance(value, str) or len(value) != 10:
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def _add_days(value: str, days: int) -> str:
    return (date.fromisoformat(value) + timedelta(days=days)).isoformat()


def _shift_all(value: str, why: str) -> list[tuple[str, str]]:
    return [
        (_add_days(value, -1), f"one day before ({why})"),
        (value, f"same day ({why})"),
        (_add_days(value, 1), f"one day after ({why})"),
    ]
